const derive=async(pass,salt)=>{const key=await crypto.subtle.importKey('raw',encoder.encode(pass),'PBKDF2',false,['deriveBits']);return hex(await crypto.subtle.deriveBits({name:'PBKDF2',salt:encoder.encode(salt),iterations:180000,hash:'SHA-256'},key,256))};
const authorized=async(r,env)=>{const t=(r.headers.get('authorization')||'').replace(/^Bearer /i,'');if(!t)return null;const hash=await digest(t);return await env.DB.prepare('SELECT p.id,p.junta_id FROM sesiones s JOIN presidentes p ON p.id=s.presidente_id WHERE s.token_hash=? AND s.expira > ? AND p.activo=1').bind(hash,now()).first()};
const syncAuth=async(r,env)=>{const token=(r.headers.get('authorization')||'').replace(/^Bearer /i,'');return !!env.SGT_SYNC_TOKEN && token.length>=32 && token===env.SGT_SYNC_TOKEN};
